import React,{useState} from 'react';import {createRoot} from 'react-dom/client';
import {OSPreviewProvider} from '../../context/OSContext';import ChatInputArea from '../../components/chat/ChatInputArea';
import ExperienceTools from '../../features/experience/Tools';import RealMediaView from '../../features/experience/RealMediaView';import ErrorDialog from '../../components/os/ErrorDialog';
import {setReliableMemoryPalaceHighWaterMark} from '../../utils/memoryPalace/highWaterMark';
import {DB} from '../../utils/db';import {ChatPrompts} from '../../utils/chatPrompts';import {DatePrompts} from '../../utils/datePrompts';import {oracleContext} from '../../features/experience/oracle';import {formatMessageForPrompt} from '../../utils/messageFormat';
const id='qa-experience-'+crypto.randomUUID();
function App(){const [input,setInput]=useState('草稿不会丢'),[panel,setPanel]=useState<any>('none'),[rows,setRows]=useState<any[]>([]),[result,setResult]=useState(''),[failure,setFailure]=useState<any>(null);
 const send=async(m:any)=>{await DB.saveCharacter({id,name:'测试角色'} as any);await DB.saveMessage({charId:id,role:'user',type:'text',...m});setRows(await DB.getMessagesByCharId(id,true));};
 return <OSPreviewProvider value={{showError:(title:string,details:string)=>setFailure({title,details}),characters:[],userProfile:{name:'User'}} as any}><main className="p-3 flex flex-col gap-3 text-stone-700"><h1>真实媒体和输入切换验收</h1><ExperienceTools scopeId={id} onSend={send} inPerson/><div>{rows.map(r=><div key={r.id}>{r.metadata?.realMedia?<RealMediaView value={r.metadata.realMedia}/>:<p>{r.content}</p>}</div>)}</div><button onClick={()=>void(async()=>{try{const all=await DB.getMessagesByCharId(id,true),media=all.find(m=>m.metadata?.realMedia);if(!media||media.metadata!.realMedia.frames.length!==6)throw Error('没有六帧');const char={id,name:'测试角色',contextLimit:100} as any;const chat=ChatPrompts.buildMessageHistory([media],100,char,{name:'User'} as any,[]).apiMessages;if(!JSON.stringify(chat).includes('image_url'))throw Error('聊天没有图片');const date=await DatePrompts.buildSessionPayload({char,userProfile:{name:'User'} as any,allMsgs:[media],emojis:[],userText:media.content,variant:'send'});if(!JSON.stringify(date).includes('image_url'))throw Error('见面没有图片');if(!(await oracleContext(id)).includes('桂花糖'))throw Error('道具未生效');if(!all.map(m=>formatMessageForPrompt(m,'角色','User')).join('\n').includes('真实视频'))throw Error('记忆没有可读文本');setResult('PASS: 六帧、聊天与见面视觉上下文、用户道具与记忆文本');}catch(e){setResult('FAIL: '+String(e));}})()}>验证媒体与道具上下文</button><button onClick={()=>void(async()=>{const all=await DB.getMessagesByCharId(id,true),last=all.at(-1)!;await setReliableMemoryPalaceHighWaterMark(id,last.id);await DB.saveCharacter({id,name:'测试角色',contextRangeMode:'adaptive',contextFollowsMemoryPalaceHwm:true,contextRangePolicyVersion:1,hideBeforeMessageId:last.id+1} as any);setResult('已准备可清理归档');})()}>准备归档清理验收</button><pre>{result}</pre><div style={{height:500}}><ChatInputArea input={input} setInput={setInput} isTyping={false} selectionMode={false} showPanel={panel} setShowPanel={setPanel} onSend={()=>{}} onGenerate={()=>{}} onDeleteSelected={()=>{}} selectedCount={0} emojis={[{name:'测试',url:'data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///ywAAAAAAQABAAACAUwAOw=='}] as any} onPanelAction={()=>{}} onImageSelect={()=>{}} isSummarizing={false} onReroll={()=>{}} canReroll={false}/></div><output aria-label="当前面板">{panel}</output></main><ErrorDialog isOpen={!!failure} title={failure?.title||''} details={failure?.details||''} onClose={()=>setFailure(null)}/></OSPreviewProvider>;
}createRoot(document.getElementById('root')!).render(<App/>);
